fn gcd_calc(m: u32, n: u32) -> u32 {
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }

    a
}

fn main() {
    // Example usage
    let m = 48;
    let n = 18;
    let result = gcd_calc(m, n);
    println!("The GCD of {} and {} is {}", m, n, result); // Output: The GCD of 48 and 18 is 6
}